import { type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

export const openAllLayoutAndAssertPanels = async (page: Page) => {
  await test.step("Switch to All layout", async () => {
    await ui.viewMenu.actions(page).switchToAll();
  });

  await test.step("Assert chat, canvas, and side panel are visible", async () => {
    await ui.inspectorShell.assertions(page).shellIsReady();
    await ui.inspectorCanvas.assertions(page).inspectorCanvasIsVisible();
    await ui.viewMenu.assertions(page).sidePanelIsVisible();
  });
};

export const openEventDetailsInAllLayoutAndAssert = async (page: Page) => {
  await openAllLayoutAndAssertPanels(page);

  await test.step("Open event details from conversation log", async () => {
    await ui.conversationLog.actions(page).clickConversationEvent("Flow welcome started");
    await ui.eventDetails.assertions(page).panelIsVisible("Flow event");
    await ui.inspectorCanvas.assertions(page).flowCanvasIsVisible();
  });
};

export const closeEventDetailsAndAssertSidePanelRestored = async (page: Page) => {
  await test.step("Close event details and restore side panel content", async () => {
    await ui.eventDetails.actions(page).close();
    await ui.eventDetails.assertions(page).panelIsHidden();
    await ui.viewMenu.assertions(page).sidePanelIsVisible();
    await ui.historyTimeline.assertions(page).timelineIsVisible({ timeout: 15000 });
  });
};
